/**
 * オセアニア大陸盤面のクイズ(第一弾: 3問のプレビュー)。
 *
 * 難易度は他の盤面と同じ1〜10、基準は「オセアニアの外にいる一般的な人が
 * どれくらい答えられそうか」。都市カードに書いた事実をそのまま答えにせず、
 * 隣接する事実を選んでいる(例: ラウトカのカードは鉄道そのものの話に絞り、
 * それを支えたインド系移民労働の話はここで問う)。
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

/** 1問を組み立てる。`o` は選択肢の配列、`a` は正解の添字。 */
function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

